-- 2026-11-19 每日收录：Q1K3、X-Type、Bounce Back、虫群模拟器、Synergism，均为 embed（站内打开原作）。
-- 只插入，不改已有行；INSERT OR IGNORE 防止与本地 jiwan.sql 重复。

INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('q1k3', 'Q1K3', 'Q1K3', 'q1k3 quake sheji fps diyi renshen phoboslab dominic szablewski', 'Dominic Szablewski (Phoboslab)', '', '', NULL, '', 0, 2021, 'action', '["射击","动作","3D"]', 15, 0.1, 'io', 'https://phoboslab.org/q1k3/', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '在 13KB 里塞进一整个类 Quake 关卡', '一款迷你第一人称射击：点击进入后用鼠标瞄准、键盘移动，清掉走廊里的敌人。', 'A tiny first-person shooter: click to start, look with the mouse, move with the keys, and clear the enemies in the corridors.', '由 Dominic Szablewski（Phoboslab）制作，是 2021 年 js13kGames 的作品，源码以 MIT 许可在 GitHub 发布。原页托管在 phoboslab.org/q1k3，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Dominic Szablewski (Phoboslab) for js13kGames 2021; the source is MIT-licensed on GitHub. Hosted at phoboslab.org/q1k3; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/q1k3.jpg', 1280, 800, 'center', '["assets/posters/q1k3.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -33, 1795053600000, 'A Quake-like stage packed into 13 KB.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('xtype', 'X-Type', 'X-Type', 'xtype x-type sheji feichuan zongxiang phoboslab dominic szablewski', 'Dominic Szablewski (Phoboslab)', '', '', NULL, '', 0, 2012, 'action', '["射击","动作"]', 210, 0.08, 'io', 'https://phoboslab.org/xtype/', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '驾驶小飞船，把来袭的敌机打成碎片', '一款纵向射击：方向键或 WASD 移动，鼠标开火。关卡会越来越密，尽量撑下去。', 'A vertical shooter: move with the arrow keys or WASD, fire with the mouse, and last as the waves get denser.', '由 Dominic Szablewski（Phoboslab）制作，音乐由 Andreas Lösch 创作，2012 年起在 phoboslab.org/xtype 公开发布。原页托管在 phoboslab.org/xtype，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Dominic Szablewski (Phoboslab) with music by Andreas Lösch, and published on phoboslab.org/xtype since 2012. Hosted at phoboslab.org/xtype; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/xtype.jpg', 1280, 800, 'center', '["assets/posters/xtype.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -32, 1795053600000, 'Fly a small ship and blast the incoming waves.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('bounce-back', 'Bounce Back', 'Bounce Back', 'bounce back tanhui tanhuilai xuanbiao maoxian frank force killedbyapixel', 'Frank Force (KilledByAPixel)', '', '', NULL, '', 0, 2019, 'action', '["动作","冒险","像素"]', 120, 0.1, 'io', 'https://killedbyapixel.github.io/BounceBack/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '丢出回旋镖，再把它接回来', '向塞尔达致敬的小冒险：走过去、丢出回旋镖、接住它，一路清掉草丛里的敌人。', 'A Zelda-inspired mini adventure: walk, throw a boomerang, catch it, and clear the enemies in the grass.', '由 Frank Force（KilledByAPixel）制作，是 2019 年 js13kGames 的作品，源码以 GPL-2.0 许可在 GitHub 发布。原页托管在 killedbyapixel.github.io/BounceBack，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Frank Force (KilledByAPixel) for js13kGames 2019; the source is GPL-2.0-licensed on GitHub. Hosted at killedbyapixel.github.io/BounceBack; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/bounce-back.jpg', 1280, 800, 'center', '["assets/posters/bounce-back.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -31, 1795053600000, 'Throw the boomerang, then catch it on the way back.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('swarm-sim', '虫群模拟器', 'Swarm Simulator', 'chongqun moniqi chongqunmoniqi swarm simulator evan rosson', 'Evan Rosson', '', '', NULL, '', 0, 2014, 'idle', '["放置","策略"]', 200, 0.08, 'clicker', 'https://swarmsim.github.io/', 0, 0, 0, 1, 0, 0, 1, 'long', 'hosted', '从几只幼虫开始，养成一整支虫群', '一款放置游戏：用肉和幼虫孵化工蜂，再一步步把虫群扩张到天文数字。', 'An idle game: spend meat and larvae to hatch drones, then grow a swarm into astronomical numbers.', '由 Evan Rosson 制作，源码以 GPL-3.0 许可在 GitHub 发布。原页托管在 swarmsim.github.io，不是即玩的作品。在即玩里直接打开原作。存档保存在浏览器本地，开玩不用登录。', 'Made by Evan Rosson; the source is GPL-3.0-licensed on GitHub. Hosted at swarmsim.github.io; it is not a Jiwan original. It opens here. Saves stay in your browser; no account needed.', 'assets/posters/swarm-sim.jpg', 1280, 800, 'center', '["assets/posters/swarm-sim.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -30, 1795053600000, 'Start with a few larvae, and grow an entire swarm.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('synergism', 'Synergism', 'Synergism', 'synergism xietong xietongzhuyi platonic khafra fangzhi', 'Platonic 与 Khafra', '', '', NULL, '', 0, 2020, 'idle', '["放置","策略"]', 280, 0.1, 'clicker', 'https://synergism.cc/', 0, 0, 0, 1, 0, 0, 1, 'long', 'hosted', '从 100 枚硬币开始，让一切彼此加成', '一款层数很多的放置游戏：雇工人、叠转生，让建筑和升级互相放大。', 'A many-layered idle game: hire workers, prestige, and let buildings and upgrades amplify each other.', '由 Platonic 与 Khafra 制作，源码以 MIT 许可在 GitHub 发布。2020 年起在 synergism.cc 公开发布。原页托管在 synergism.cc，不是即玩的作品。在即玩里直接打开原作。存档保存在浏览器本地，开玩不用登录。可选的 Steam 版不影响网页免费游玩。', 'Made by Platonic and Khafra; the source is MIT-licensed on GitHub. Published on synergism.cc since 2020. Hosted at synergism.cc; it is not a Jiwan original. It opens here. Saves stay in your browser; no account needed. The optional Steam edition is not required to play on the web.', 'assets/posters/synergism.jpg', 1280, 800, 'center', '["assets/posters/synergism.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -29, 1795053600000, 'Start with 100 coins, and let everything amplify everything else.', '', '', 1);
